export { loader, action };

const NAV_ITEMS = [
  { key: "organization", label: "Organization Settings", icon: "organization" },
  { key: "connection", label: "Zoho Books Connection", icon: "link" },
  { key: "warehouses", label: "Warehouse Mapping", icon: "inventory" },
  { key: "tax", label: "Tax Settings", icon: "receipt" },
  { key: "accounts", label: "Account Settings", icon: "bank" },
];
const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
function Icon({ type }) { return <s-icon type={type}></s-icon>; }
function display(value, fallback = "—") { return value === null || value === undefined || value === "" ? fallback : value; }
function monthName(value) { return MONTHS[Number(value) - 1] || value || "—"; }
function fiscalYear(value) { const start = Number(value) || 1; const end = start === 1 ? 12 : start === 12 ? 11 : start - 1; return `${monthName(start)} – ${monthName(end)}`; }
function formatDate(value) { return value ? new Date(value).toLocaleString([], { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }) : "—"; }
function shopifyNumericId(gid) { return gid ? gid.split("/").pop() : null; }
function SettingCard({ icon, tone = "blue", label, value }) { return <div className="setting-card"><div className={`setting-icon ${tone}`}><Icon type={icon} /></div><div className="setting-copy"><span>{label}</span><strong>{value}</strong></div></div>; }

